CREATE FUNCTION public.evidence_object_access(p_name text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.has_occurrence_access(split_part(p_name,'/',1)::uuid); EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
REVOKE ALL ON FUNCTION public.evidence_object_access(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.evidence_object_access(text) TO authenticated;
CREATE POLICY evidence_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='evidences' AND public.evidence_object_access(name));
CREATE POLICY evidence_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='evidences' AND public.evidence_object_access(name));
CREATE FUNCTION public.validate_attachment_upload() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.occurrences WHERE id=NEW.occurrence_id FOR UPDATE; IF NEW.occurrence_id IS NULL OR NEW.storage_path NOT LIKE NEW.occurrence_id::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='evidences' AND name=NEW.storage_path) THEN RAISE EXCEPTION 'Arquivo não encontrado ou vínculo inválido'; END IF; IF (SELECT count(*) FROM public.attachments WHERE occurrence_id=NEW.occurrence_id)>=10 THEN RAISE EXCEPTION 'Limite de 10 anexos por ocorrência'; END IF; IF NEW.size_bytes IS NULL OR NEW.size_bytes<=0 OR NEW.size_bytes>15728640 THEN RAISE EXCEPTION 'Limite de 15 MB por arquivo'; END IF; RETURN NEW; END $$;
CREATE TRIGGER attachment_upload_guard BEFORE INSERT ON public.attachments FOR EACH ROW EXECUTE FUNCTION public.validate_attachment_upload();
CREATE TABLE public.public_link_attempts(key text PRIMARY KEY,window_start timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0); GRANT ALL ON public.public_link_attempts TO service_role; ALTER TABLE public.public_link_attempts ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.limit_public_link(p_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.public_link_attempts(key,attempts) VALUES(p_key,1) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN public.public_link_attempts.window_start<now()-interval '1 minute' THEN 1 ELSE public.public_link_attempts.attempts+1 END,window_start=CASE WHEN public.public_link_attempts.window_start<now()-interval '1 minute' THEN now() ELSE public.public_link_attempts.window_start END RETURNING attempts INTO n; RETURN n<=30; END $$;
REVOKE ALL ON FUNCTION public.limit_public_link(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.limit_public_link(text) TO service_role;
CREATE FUNCTION public.answer_customer_evaluation(p_hash text,p_resolved public.eval_resolved,p_csat integer,p_ces integer,p_missing text,p_comment text,p_reopen boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.evaluations; o public.occurrences; BEGIN IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO e FROM public.evaluations WHERE token_hash=p_hash FOR UPDATE; IF e.id IS NULL THEN RAISE EXCEPTION 'Link inválido ou expirado'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=e.occurrence_id FOR UPDATE; IF e.cycle<>o.reopen_count+1 THEN RAISE EXCEPTION 'Link inválido ou expirado'; END IF; IF p_reopen THEN IF o.status NOT IN ('closed_resolved','closed_no_evaluation') OR o.closed_at IS NULL OR now()>o.closed_at+interval '15 days' OR length(trim(coalesce(p_missing,'')))=0 THEN RAISE EXCEPTION 'Link inválido ou expirado'; END IF; RETURN public.reopen_occurrence_from_customer(o.id,p_missing); END IF;
IF e.answered_at IS NOT NULL OR now()>e.token_expires_at OR o.status<>'solution_proposed' THEN RAISE EXCEPTION 'Link inválido ou expirado'; END IF; IF p_resolved IS NULL OR p_csat IS NULL OR p_csat NOT BETWEEN 1 AND 5 OR p_ces IS NULL OR p_ces NOT BETWEEN 1 AND 7 OR length(coalesce(p_comment,''))>1000 OR (p_resolved IN ('partial','no') AND length(trim(coalesce(p_missing,'')))=0) THEN RAISE EXCEPTION 'Resposta incompleta'; END IF;
UPDATE public.evaluations SET answered_at=now(),resolved=p_resolved,csat=p_csat,ces=p_ces,missing_text=p_missing,comment=p_comment WHERE id=e.id; IF p_resolved='yes' THEN UPDATE public.occurrences SET status='closed_resolved',closed_at=now(),updated_at=now() WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,body,from_status,to_status) VALUES(o.id,'evaluation','customer','Cliente confirmou a solução',o.status,'closed_resolved'); RETURN jsonb_build_object('status','closed_resolved'); END IF; RETURN public.reopen_occurrence_from_customer(o.id,p_missing); END $$;
REVOKE ALL ON FUNCTION public.answer_customer_evaluation(text,public.eval_resolved,integer,integer,text,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.answer_customer_evaluation(text,public.eval_resolved,integer,integer,text,text,boolean) TO service_role;